            // ensure min < max for each dimension
            for (int d = 0; d < 3; d++) {
                if (fish[i][d] > fish[i][d+3]) { long t = fish[i][d]; fish[i][d] = fish[i][d+3]; fish[i][d+3] = t; }
            }
        }
        long[] xs = coords(fish, 0), ys = coords(fish, 1), zs = coords(fish, 2);
        long total = 0;
        for (int i = 0; i < xs.length-1; i++) {
            for (int j = 0; j < ys.length-1; j++) {
                for (int k = 0; k < zs.length-1; k++) {
                    long mx = xs[i], my = ys[j], mz = zs[k];
                    int cnt = 0;
                    for (int f = 0; f < N; f++) {
                        if (fish[f][0] <= mx && mx < fish[f][3] && fish[f][1] <= my && my < fish[f][4] && fish[f][2] <= mz && mz < fish[f][5]) cnt++;
                    }
                    if (cnt >= K) total += (xs[i+1]-xs[i])*(ys[j+1]-ys[j])*(zs[k+1]-zs[k]);
                }
            }
        }
        System.out.println(total);
    }
    static long[] coords(long[][] fish, int d) {
        TreeSet<Long> set = new TreeSet<>();
        for (long[] f : fish) { set.add(f[d]); set.add(f[d+3]); }
        long[] arr = new long[set.size()]; int i=0; for (long v : set) arr[i++]=v; return arr;
    }
