import java.io.*;
import java.util.*;

/*
 * Sweep line in 3D with coordinate compression.
 *
 * We need the total volume covered by at least K axis-aligned rectangular boxes.
 *
 * Idea:
 * 1) Compress x, y, z coordinates from all box boundaries.
 * 2) For each compressed x-slab, maintain a 2D difference array over (y, z)
 *    representing how many boxes are active in that x interval.
 * 3) For each x-slab, reconstruct coverage counts on yz-cells via prefix sums,
 *    sum area of cells with count >= K, then multiply by slab width in x.
 *
 * Complexity:
 * Let X, Y, Z be number of unique coordinates on each axis.
 * Updating events: O(N)
 * For each x-slab: O(Y*Z)
 * Since typical constraints for this classic problem are small enough for compression+sweep,
 * this is acceptable.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Box {
        long x1, y1, z1, x2, y2, z2;
        Box(long x1, long y1, long z1, long x2, long y2, long z2) {
            this.x1 = Math.min(x1, x2);
            this.y1 = Math.min(y1, y2);
            this.z1 = Math.min(z1, z2);
            this.x2 = Math.max(x1, x2);
            this.y2 = Math.max(y1, y2);
            this.z2 = Math.max(z1, z2);
        }
    }

    static class Event {
        int xIdx;
        int y1, y2, z1, z2;
        int delta;
        Event(int xIdx, int y1, int y2, int z1, int z2, int delta) {
            this.xIdx = xIdx;
            this.y1 = y1;
            this.y2 = y2;
            this.z1 = z1;
            this.z2 = z2;
            this.delta = delta;
        }
    }

    static int lowerBound(long[] a, long key) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] < key) l = m + 1;
            else r = m;
        }
        return l;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int K = fs.nextInt();

        Box[] boxes = new Box[N];
        long[] xs = new long[2 * N];
        long[] ys = new long[2 * N];
        long[] zs = new long[2 * N];

        for (int i = 0; i < N; i++) {
            long x1 = fs.nextLong();
            long y1 = fs.nextLong();
            long z1 = fs.nextLong();
            long x2 = fs.nextLong();
            long y2 = fs.nextLong();
            long z2 = fs.nextLong();
            boxes[i] = new Box(x1, y1, z1, x2, y2, z2);
            xs[2 * i] = boxes[i].x1;
            xs[2 * i + 1] = boxes[i].x2;
            ys[2 * i] = boxes[i].y1;
            ys[2 * i + 1] = boxes[i].y2;
            zs[2 * i] = boxes[i].z1;
            zs[2 * i + 1] = boxes[i].z2;
        }

        xs = Arrays.stream(xs).distinct().sorted().toArray();
        ys = Arrays.stream(ys).distinct().sorted().toArray();
        zs = Arrays.stream(zs).distinct().sorted().toArray();

        int X = xs.length, Y = ys.length, Z = zs.length;

        ArrayList<Event>[] eventsAtX = new ArrayList[X];
        for (int i = 0; i < X; i++) eventsAtX[i] = new ArrayList<>();

        for (Box b : boxes) {
            if (b.x1 == b.x2 || b.y1 == b.y2 || b.z1 == b.z2) continue; // zero volume
            int x1 = lowerBound(xs, b.x1);
            int x2 = lowerBound(xs, b.x2);
            int y1 = lowerBound(ys, b.y1);
            int y2 = lowerBound(ys, b.y2);
            int z1 = lowerBound(zs, b.z1);
            int z2 = lowerBound(zs, b.z2);

            eventsAtX[x1].add(new Event(x1, y1, y2, z1, z2, +1));
            eventsAtX[x2].add(new Event(x2, y1, y2, z1, z2, -1));
        }

        // 2D difference array on compressed y-z grid points
        int[][] diff = new int[Y + 1][Z + 1];
        long answer = 0L;

        for (int xi = 0; xi < X - 1; xi++) {
            for (Event e : eventsAtX[xi]) {
                diff[e.y1][e.z1] += e.delta;
                diff[e.y2][e.z1] -= e.delta;
                diff[e.y1][e.z2] -= e.delta;
                diff[e.y2][e.z2] += e.delta;
            }

            long dx = xs[xi + 1] - xs[xi];
            if (dx == 0) continue;

            long coveredArea = 0L;

            int[][] pref = new int[Y][Z];
            for (int y = 0; y < Y - 1; y++) {
                for (int z = 0; z < Z - 1; z++) {
                    int val = diff[y][z];
                    if (y > 0) val += pref[y - 1][z];
                    if (z > 0) val += pref[y][z - 1];
                    if (y > 0 && z > 0) val -= pref[y - 1][z - 1];
                    pref[y][z] = val;

                    if (val >= K) {
                        long dy = ys[y + 1] - ys[y];
                        long dz = zs[z + 1] - zs[z];
                        coveredArea += dy * dz;
                    }
                }
            }

            answer += coveredArea * dx;
        }

        System.out.println(answer);
    }
}

