        int x1, y1, z1, x2, y2, z2;
        cin >> x1 >> y1 >> z1 >> x2 >> y2 >> z2;
        boxes[i] = {x1, y1, z1, x2, y2, z2};
        xs.push_back(x1); xs.push_back(x2);
        ys.push_back(y1); ys.push_back(y2);
        zs.push_back(z1); zs.push_back(z2);
    }

    // coordinate compression
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    sort(zs.begin(), zs.end());
    zs.erase(unique(zs.begin(), zs.end()), zs.end());

    int X = xs.size() - 1;
    int Y = ys.size() - 1;
    int Z = zs.size() - 1;

    vector<vector<vector<int>>> diff(X, vector<vector<int>>(Y, vector<int>(Z, 0)));

    for (auto &b : boxes) {
        int x1 = lower_bound(xs.begin(), xs.end(), b[0]) - xs.begin();
        int y1 = lower_bound(ys.begin(), ys.end(), b[1]) - ys.begin();
        int z1 = lower_bound(zs.begin(), zs.end(), b[2]) - zs.begin();
        int x2 = lower_bound(xs.begin(), xs.end(), b[3]) - xs.begin();
        int y2 = lower_bound(ys.begin(), ys.end(), b[4]) - ys.begin();
        int z2 = lower_bound(zs.begin(), zs.end(), b[5]) - zs.begin();

        // 3D difference
        diff[x1][y1][z1] += 1;
        if (x2 < X) diff[x2][y1][z1] -= 1;
        if (y2 < Y) diff[x1][y2][z1] -= 1;
        if (z2 < Z) diff[x1][y1][z2] -= 1;
        if (x2 < X && y2 < Y) diff[x2][y2][z1] += 1;
        if (x2 < X && z2 < Z) diff[x2][y1][z2] += 1;
        if (y2 < Y && z2 < Z) diff[x1][y2][z2] += 1;
        if (x2 < X && y2 < Y && z2 < Z) diff[x2][y2][z2] -= 1;
    }

    // prefix sum
    for (int i = 0; i < X; i++) {
        for (int j = 0; j < Y; j++) {
            for (int k = 0; k < Z; k++) {
                if (i > 0) diff[i][j][k] += diff[i-1][j][k];
                if (j > 0) diff[i][j][k] += diff[i][j-1][k];
                if (k > 0) diff[i][j][k] += diff[i][j][k-1];
                if (i > 0 && j > 0) diff[i][j][k] -= diff[i-1][j-1][k];
                if (i > 0 && k > 0) diff[i][j][k] -= diff[i-1][j][k-1];
                if (j > 0 && k > 0) diff[i][j][k] -= diff[i][j-1][k-1];
                if (i > 0 && j > 0 && k > 0) diff[i][j][k] += diff[i-1][j-1][k-1];
            }
        }
    }

    long long volume = 0;
    for (int i = 0; i < X; i++) {
        for (int j = 0; j < Y; j++) {
            for (int k = 0; k < Z; k++) {
                if (diff[i][j][k] >= K) {
                    long long dx = xs[i+1] - xs[i];
                    long long dy = ys[j+1] - ys[j];
                    long long dz = zs[k+1] - zs[k];
                    volume += dx * dy * dz;
                }
            }
        }
    }

    cout << volume << "\n";

    return 0;
}

