        if (z1[i] > z2[i]) swap(z1[i], z2[i]);
        xs.push_back(x1[i]); xs.push_back(x2[i]);
        ys.push_back(y1[i]); ys.push_back(y2[i]);
        zs.push_back(z1[i]); zs.push_back(z2[i]);
    }

    sort(xs.begin(), xs.end()); xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end()); ys.erase(unique(ys.begin(), ys.end()), ys.end());
    sort(zs.begin(), zs.end()); zs.erase(unique(zs.begin(), zs.end()), zs.end());

    long long ans = 0;

    for (int i = 0; i + 1 < (int)xs.size(); i++) {
        for (int j = 0; j + 1 < (int)ys.size(); j++) {
            for (int k = 0; k + 1 < (int)zs.size(); k++) {
                // Representative point: midpoint (or just use left endpoint for containment check)
                long long cx = xs[i]; // cell spans [xs[i], xs[i+1])
                long long cy = ys[j];
                long long cz = zs[k];

                int cnt = 0;
                for (int p = 0; p < N; p++) {
                    if (cx >= x1[p] && cx < x2[p] &&
                        cy >= y1[p] && cy < y2[p] &&
                        cz >= z1[p] && cz < z2[p]) {
                        cnt++;
                    }
                }

                if (cnt >= K) {
                    long long vol = (xs[i+1] - xs[i]) * (ys[j+1] - ys[j]) * (zs[k+1] - zs[k]);
                    ans += vol;
                }
            }
        }
    }

    cout << ans << endl;

