struct Event {
    int x1, x2;
    int delta;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    struct Box {
        long long x1, y1, z1, x2, y2, z2;
    };

    vector<Box> boxes(N);
    vector<long long> xs, ys, zs;

    for (int i = 0; i < N; ++i) {
        long long x1, y1, z1, x2, y2, z2;
        cin >> x1 >> y1 >> z1 >> x2 >> y2 >> z2;
        if (x1 > x2) swap(x1, x2);
        if (y1 > y2) swap(y1, y2);
        if (z1 > z2) swap(z1, z2);
        boxes[i] = {x1, y1, z1, x2, y2, z2};
        xs.push_back(x1);
        xs.push_back(x2);
        ys.push_back(y1);
        ys.push_back(y2);
        zs.push_back(z1);
        zs.push_back(z2);
    }

    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    sort(zs.begin(), zs.end());
    zs.erase(unique(zs.begin(), zs.end()), zs.end());

    int X = (int)xs.size();
    int Y = (int)ys.size();
    int Z = (int)zs.size();

    vector<vector<vector<Event>>> addZ(Z), remZ(Z);
    for (int z = 0; z < Z; ++z) {
        addZ[z].resize(Y);
        remZ[z].resize(Y);
    }

    auto getX = [&](long long v) {
        return (int)(lower_bound(xs.begin(), xs.end(), v) - xs.begin());
    };
    auto getY = [&](long long v) {
        return (int)(lower_bound(ys.begin(), ys.end(), v) - ys.begin());
    };
    auto getZ = [&](long long v) {
        return (int)(lower_bound(zs.begin(), zs.end(), v) - zs.begin());
    };

    for (auto &b : boxes) {
        int x1 = getX(b.x1), x2 = getX(b.x2);
        int y1 = getY(b.y1), y2 = getY(b.y2);
        int z1 = getZ(b.z1), z2 = getZ(b.z2);

        for (int y = y1; y < y2; ++y) {
            addZ[z1][y].push_back({x1, x2, +1});
            remZ[z2][y].push_back({x1, x2, -1});
        }
    }

    long long answer = 0;
    vector<int> coverX(max(0, X - 1), 0);

    for (int z = 0; z < Z - 1; ++z) {
        vector<vector<Event>> rowEvents(Y);

        for (int y = 0; y < Y; ++y) {
            for (auto &e : addZ[z][y]) rowEvents[y].push_back(e);
            for (auto &e : remZ[z][y]) rowEvents[y].push_back(e);
        }

        fill(coverX.begin(), coverX.end(), 0);
        long long areaYZ = 0;

        for (int y = 0; y < Y - 1; ++y) {
            for (auto &e : rowEvents[y]) {
                for (int x = e.x1; x < e.x2; ++x) {
                    coverX[x] += e.delta;
                }
            }

            long long coveredXLen = 0;
            for (int x = 0; x < X - 1; ++x) {
                if (coverX[x] >= K) {
                    coveredXLen += xs[x + 1] - xs[x];
                }
            }

            long long dy = ys[y + 1] - ys[y];
            areaYZ += coveredXLen * dy;
        }

        long long dz = zs[z + 1] - zs[z];
        answer += areaYZ * dz;
    }

    cout << answer << '\n';
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_N 50
#define MAX_COORD 200

typedef struct {
    int x1, y1, z1, x2, y2, z2;
} Box;

// Coordinate compression arrays
int xs[MAX_COORD], ys[MAX_COORD], zs[MAX_COORD];
int xn, yn, zn;

int cmp(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

int main() {
    int N, K;
    scanf("%d %d", &N, &K);

    Box boxes[MAX_N];
    int xi = 0, yi = 0, zi = 0;

    for (int i = 0; i < N; i++) {
        scanf("%d %d %d %d %d %d", 
              &boxes[i].x1, &boxes[i].y1, &boxes[i].z1,
              &boxes[i].x2, &boxes[i].y2, &boxes[i].z2);
        xs[xi++] = boxes[i].x1;
        xs[xi++] = boxes[i].x2;
        ys[yi++] = boxes[i].y1;
        ys[yi++] = boxes[i].y2;
        zs[zi++] = boxes[i].z1;
        zs[zi++] = boxes[i].z2;
    }

    // Sort and deduplicate coordinates
    qsort(xs, xi, sizeof(int), cmp);
    qsort(ys, yi, sizeof(int), cmp);
    qsort(zs, zi, sizeof(int), cmp);

    xn = 1;
    for (int i = 1; i < xi; i++)
        if (xs[i] != xs[xn-1]) xs[xn++] = xs[i];

    yn = 1;
    for (int i = 1; i < yi; i++)
        if (ys[i] != ys[yn-1]) ys[yn++] = ys[i];

    zn = 1;
    for (int i = 1; i < zi; i++)
        if (zs[i] != zs[zn-1]) zs[zn++] = zs[i];

    // 3D grid for counting overlaps
    int grid[MAX_COORD][MAX_COORD][MAX_COORD] = {0};

    // Mark each box in compressed grid
    for (int b = 0; b < N; b++) {
        // Find compressed indices
        int ix1 = 0, ix2 = 0, iy1 = 0, iy2 = 0, iz1 = 0, iz2 = 0;

        // Binary search for x1
        int lo = 0, hi = xn-1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (xs[mid] == boxes[b].x1) { ix1 = mid; break; }
            if (xs[mid] < boxes[b].x1) lo = mid + 1;
            else hi = mid - 1;
        }
        // Binary search for x2
        lo = 0; hi = xn-1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (xs[mid] == boxes[b].x2) { ix2 = mid; break; }
            if (xs[mid] < boxes[b].x2) lo = mid + 1;
            else hi = mid - 1;
        }
        // Binary search for y1
        lo = 0; hi = yn-1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (ys[mid] == boxes[b].y1) { iy1 = mid; break; }
            if (ys[mid] < boxes[b].y1) lo = mid + 1;
            else hi = mid - 1;
        }
        // Binary search for y2
        lo = 0; hi = yn-1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (ys[mid] == boxes[b].y2) { iy2 = mid; break; }
            if (ys[mid] < boxes[b].y2) lo = mid + 1;
            else hi = mid - 1;
        }
        // Binary search for z1
        lo = 0; hi = zn-1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (zs[mid] == boxes[b].z1) { iz1 = mid; break; }
            if (zs[mid] < boxes[b].z1) lo = mid + 1;
            else hi = mid - 1;
        }
        // Binary search for z2
        lo = 0; hi = zn-1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (zs[mid] == boxes[b].z2) { iz2 = mid; break; }
            if (zs[mid] < boxes[b].z2) lo = mid + 1;
            else hi = mid - 1;
        }

        // Mark all cells in this box
        for (int i = ix1; i < ix2; i++)
            for (int j = iy1; j < iy2; j++)
                for (int k = iz1; k < iz2; k++)
                    grid[i][j][k]++;
    }

    // Calculate total volume where overlap >= K
    long long total_volume = 0;
    for (int i = 0; i < xn - 1; i++) {
        long long dx = xs[i+1] - xs[i];
        for (int j = 0; j < yn - 1; j++) {
            long long dy = ys[j+1] - ys[j];
            for (int k = 0; k < zn - 1; k++) {
                if (grid[i][j][k] >= K) {
                    long long dz = zs[k+1] - zs[k];
                    total_volume += dx * dy * dz;
                }
            }
        }
    }

    printf("%lld\n", total_volume);

    return 0;
}

