        if (x1a[i] > x2a[i]) { double t = x1a[i]; x1a[i] = x2a[i]; x2a[i] = t; }
        if (y1a[i] > y2a[i]) { double t = y1a[i]; y1a[i] = y2a[i]; y2a[i] = t; }
        if (z1a[i] > z2a[i]) { double t = z1a[i]; z1a[i] = z2a[i]; z2a[i] = t; }
        xs[nx++] = x1a[i]; xs[nx++] = x2a[i];
        ys[ny++] = y1a[i]; ys[ny++] = y2a[i];
        zs[nz++] = z1a[i]; zs[nz++] = z2a[i];
    }
    qsort(xs, nx, sizeof(double), cmp);
    qsort(ys, ny, sizeof(double), cmp);
    qsort(zs, nz, sizeof(double), cmp);

    double total = 0.0;
    for (int i = 0; i < nx-1; i++) {
