        for (int j = 0; j < ny-1; j++) {
            double yj = ys[j], yj1 = ys[j+1];
            if (yj >= yj1) continue;
            double dy = yj1 - yj;
            double ym = (yj + yj1) / 2.0;
            for (int k = 0; k < nz-1; k++) {
                double zk = zs[k], zk1 = zs[k+1];
                if (zk >= zk1) continue;
                double dz = zk1 - zk;
                double zm = (zk + zk1) / 2.0;
                // count habitats containing this cell
                int cnt = 0;
                for (int f = 0; f < N; f++) {
                    if (xm >= x1a[f] && xm <= x2a[f] &&
                        ym >= y1a[f] && ym <= y2a[f] &&
                        zm >= z1a[f] && zm <= z2a[f]) {
