#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll x1, y1, z1;
    ll x2, y2, z2;
} Box;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int lower_bound_ll(ll *arr, int n, ll val) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m] < val) l = m + 1;
        else r = m;
    }
    return l;
}

int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    Box *boxes = (Box *)malloc(sizeof(Box) * N);
    ll *xs = (ll *)malloc(sizeof(ll) * 2 * N);
    ll *ys = (ll *)malloc(sizeof(ll) * 2 * N);
    ll *zs = (ll *)malloc(sizeof(ll) * 2 * N);

    for (int i = 0; i < N; i++) {
        ll x1, y1, z1, x2, y2, z2;
        scanf("%lld %lld %lld %lld %lld %lld", &x1, &y1, &z1, &x2, &y2, &z2);

        if (x1 > x2) { ll t = x1; x1 = x2; x2 = t; }
        if (y1 > y2) { ll t = y1; y1 = y2; y2 = t; }
        if (z1 > z2) { ll t = z1; z1 = z2; z2 = t; }

        boxes[i].x1 = x1; boxes[i].y1 = y1; boxes[i].z1 = z1;
        boxes[i].x2 = x2; boxes[i].y2 = y2; boxes[i].z2 = z2;

        xs[2*i] = x1; xs[2*i+1] = x2;
        ys[2*i] = y1; ys[2*i+1] = y2;
        zs[2*i] = z1; zs[2*i+1] = z2;
    }

    qsort(xs, 2 * N, sizeof(ll), cmp_ll);
    qsort(ys, 2 * N, sizeof(ll), cmp_ll);
    qsort(zs, 2 * N, sizeof(ll), cmp_ll);

    int xn = 0, yn = 0, zn = 0;
    for (int i = 0; i < 2 * N; i++) {
        if (i == 0 || xs[i] != xs[i - 1]) xs[xn++] = xs[i];
        if (i == 0 || ys[i] != ys[i - 1]) ys[yn++] = ys[i];
        if (i == 0 || zs[i] != zs[i - 1]) zs[zn++] = zs[i];
    }

    int xcells = xn - 1, ycells = yn - 1, zcells = zn - 1;
    if (xcells <= 0 || ycells <= 0 || zcells <= 0) {
        printf("0\n");
        free(boxes); free(xs); free(ys); free(zs);
        return 0;
    }

    int total = xcells * ycells * zcells;
    int *cnt = (int *)calloc((size_t)total, sizeof(int));

    for (int b = 0; b < N; b++) {
        int xi1 = lower_bound_ll(xs, xn, boxes[b].x1);
        int xi2 = lower_bound_ll(xs, xn, boxes[b].x2);
        int yi1 = lower_bound_ll(ys, yn, boxes[b].y1);
        int yi2 = lower_bound_ll(ys, yn, boxes[b].y2);
        int zi1 = lower_bound_ll(zs, zn, boxes[b].z1);
        int zi2 = lower_bound_ll(zs, zn, boxes[b].z2);

        for (int i = xi1; i < xi2; i++) {
            for (int j = yi1; j < yi2; j++) {
                int base = (i * ycells + j) * zcells;
                for (int k = zi1; k < zi2; k++) {
                    cnt[base + k]++;
                }
            }
        }
    }

    ll ans = 0;
    for (int i = 0; i < xcells; i++) {
        ll dx = xs[i + 1] - xs[i];
        for (int j = 0; j < ycells; j++) {
            ll dy = ys[j + 1] - ys[j];
            int base = (i * ycells + j) * zcells;
            for (int k = 0; k < zcells; k++) {
                if (cnt[base + k] >= K) {
                    ll dz = zs[k + 1] - zs[k];
                    ans += dx * dy * dz;
                }
            }
        }
    }

    printf("%lld\n", ans);

    free(boxes);
    free(xs);
    free(ys);
    free(zs);
    free(cnt);
    return 0;
}

def solve():
    import sys
    input = sys.stdin.readline

