        prisms.append((x1, y1, z1, x2, y2, z2))
        xs.add(x1); xs.add(x2)
        ys.add(y1); ys.add(y2)
        zs.add(z1); zs.add(z2)

    xs = sorted(xs)
    ys = sorted(ys)
    zs = sorted(zs)

    x_index = {v: i for i, v in enumerate(xs)}
    y_index = {v: i for i, v in enumerate(ys)}
    z_index = {v: i for i, v in enumerate(zs)}

    nx = len(xs)
    ny = len(ys)
    nz = len(zs)

    # 3D difference array
    diff = [[[0] * (nz) for _ in range(ny)] for __ in range(nx)]

    for x1, y1, z1, x2, y2, z2 in prisms:
        ix1 = x_index[x1]
        ix2 = x_index[x2]
        iy1 = y_index[y1]
        iy2 = y_index[y2]
        iz1 = z_index[z1]
        iz2 = z_index[z2]

        diff[ix1][iy1][iz1] += 1
        diff[ix1][iy1][iz2] -= 1
        diff[ix1][iy2][iz1] -= 1
        diff[ix1][iy2][iz2] += 1
        diff[ix2][iy1][iz1] -= 1
        diff[ix2][iy1][iz2] += 1
        diff[ix2][iy2][iz1] += 1
        diff[ix2][iy2][iz2] -= 1

    # Prefix sum in 3D
    for i in range(nx):
        for j in range(ny):
            for k in range(nz):
                if i > 0:
                    diff[i][j][k] += diff[i-1][j][k]
                if j > 0:
                    diff[i][j][k] += diff[i][j-1][k]
                if k > 0:
                    diff[i][j][k] += diff[i][j][k-1]
                if i > 0 and j > 0:
                    diff[i][j][k] -= diff[i-1][j-1][k]
                if i > 0 and k > 0:
                    diff[i][j][k] -= diff[i-1][j][k-1]
                if j > 0 and k > 0:
                    diff[i][j][k] -= diff[i][j-1][k-1]
                if i > 0 and j > 0 and k > 0:
                    diff[i][j][k] += diff[i-1][j-1][k-1]

    total_volume = 0
    for i in range(nx - 1):
        dx = xs[i+1] - xs[i]
        for j in range(ny - 1):
            dy = ys[j+1] - ys[j]
            for k in range(nz - 1):
                if diff[i][j][k] >= K:
                    dz = zs[k+1] - zs[k]
                    total_volume += dx * dy * dz

    print(total_volume)

